function UICultivateEquipUpgradeLevelSetListCell:__init()
end

function UICultivateEquipUpgradeLevelSetListCell:__delete()
    self.ToggleCells = nil
end

function UICultivateEquipUpgradeLevelSetListCell:Awake()
    self.DescNode = self.controller.transform:Find("DescNode")
    KTool.SetActive(self.ToggleCell.gameObject, false)
    self.ToggleCells = {}
end

function UICultivateEquipUpgradeLevelSetListCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
