---RefreshUI
---@param screenVo ScreenVo
---@param title string
---@param selectRule table
function UICultivateEquipUpgradeLevelSetListCell:RefreshUI(screenVo, title, selectRule)
    self.TitleText.text = title
    local conditionName = screenVo.conditionName
    local id = screenVo.id
    local condition = screenVo.condition
    local parent = self.DescNode == nil and self.controller.gameObject or self.DescNode.gameObject
    for i, v in ipairs(condition) do
        local cell = self.ToggleCells[i]
        if cell == nil then
            cell = parent:AddChild(self.ToggleCell.gameObject)
            self.ToggleCells[i] = cell
            KTool.SetActive(cell.gameObject, true)
        end
        self:RefreshToggleCellUI(cell, id, condition[i], conditionName[i], selectRule)
    end


    
end

function UICultivateEquipUpgradeLevelSetListCell:RefreshToggleCellUI(cell, id, conditionId, conditionName, selectRule)
    ---@type UICultivateEquipUpgradeLevelSetToggleCell
    local env = CfUtils.GetLuaScr(cell.gameObject, SetToggleCellEnvPath)
    if isNull(env) then
        return
    end
    env:RefreshUI(id, conditionId, conditionName, selectRule)
end

